], [
    ('is_a', '$thing', 'jompus', True)
])

engine.add_rule('jompus_is_sweet', [
    ('is_a', '$thing', 'jompus', True)
], [
    ('is_sweet', '$thing', True)
])

engine.add_rule('jompus_is_zumpus', [
